        "Ανήκει στις προθέσεις διπλής χρήσης: στην ερώτηση Wo? (πού;) ακολουθεί δοτική (an der Tür), στην ερώτηση Wohin? (προς τα πού;) — αιτιατική (an die Tür). Συναιρέσεις: an dem → am, an das → ans.",
        "Για τον χρόνο χρησιμοποιείται με ημέρες και μέρη της ημέρας: am Montag, am Abend. Πολλά ρήματα απαιτούν an + αιτιατική: an dich denken (σκέφτομαι εσένα)."
