        "Το Aufs είναι τύπος αιτιατικής: auf + das Bett → aufs Bett. Στη δοτική (Wo?) δεν υπάρχει τύπος aufs: auf dem Bett.",
        "Εμφανίζεται και σε σταθερές εκφράσεις: sich aufs Wochenende freuen (περιμένω το σαββατοκύριακο με χαρά), aufs Beste (με τον καλύτερο τρόπο)."
