        "Η λέξη δεν αλλάζει μορφή. Το Bitte schön είναι πιο ευγενική εκδοχή όταν προσφέρεις κάτι («ορίστε, παρακαλώ»), το bitte sehr — ισοδύναμη παραλλαγή. Το Wie bitte? σημαίνει «ορίστε; συγγνώμη;», όταν δεν άκουσες καλά.",
