        "Ο πληθυντικός είναι die Bitten. Συχνές φράσεις: eine Bitte haben (έχω μια παράκληση), eine Bitte an jemanden richten (απευθύνω μια παράκληση σε κάποιον), eine Bitte erfüllen (ικανοποιώ μια παράκληση), die Bitte um Hilfe (η παράκληση για βοήθεια).",
        "Η λέξη bitte με μικρό είναι η λέξη ευγένειας «παρακαλώ», όχι ουσιαστικό· χρησιμοποιείται σε αιτήματα και ως απάντηση στο Danke."
