        "Το Dieser χρησιμοποιείται και στη θέση ουσιαστικού, με κατάληξη πτώσης, όταν είναι σαφές για ποιο πράγμα γίνεται λόγος: Dieser gefällt mir (αυτός μου αρέσει)."
