        "Τύποι: kennt, kannte, hat gekannt. Πάντα με αιτιατική: jemanden/etwas kennen. Στους τύπους του παρελθόντος αλλάζει το φωνήεν: kennen → kannte (με a).",
        "Διαφορά από το wissen: kennen — γνωρίζω άνθρωπο/τόπο, wissen — ξέρω ένα γεγονός: Ich kenne ihn, αλλά Ich weiß, dass er Arzt ist."
