        "Τύποι: ich kann, du kannst, er/sie/es kann, wir können, ihr könnt, sie können· παρελθόν konnte, παρακείμενος hat gekonnt. Το δεύτερο ρήμα μπαίνει σε απαρέμφατο στο τέλος της πρότασης: Ich kann heute nicht kommen.",
