        "Χρήση: in den Laden gehen (πηγαίνω στο μαγαζί), im Laden einkaufen. Σε σύνθετα: Blumenladen (ανθοπωλείο), Bioladen, Schreibwarenladen. Το μεγάλο κατάστημα τροφίμων λέγεται Supermarkt.",
        "Der Fensterladen (πληθ. die Fensterläden) είναι το παντζούρι. Το ρήμα laden (φορτώνω, φορτίζω) γράφεται με τον ίδιο τρόπο, αλλά είναι ρήμα: Ich lade mein Handy."
