        "Πληθυντικός: die Länder (χώρες)· ιστορικά και die Lande, αλλά χρησιμοποιείται σπάνια. Εκφράσεις: aufs Land fahren (πηγαίνω στην εξοχή), auf dem Land leben (ζω στην εξοχή), im Ausland / im Inland.",
