        "Τύποι: macht, machte, hat gemacht. Με αιτιατική: etwas machen. Σε πολλές εκφράσεις σχηματίζει ρηματική φράση: Spaß machen (είναι διασκεδαστικό), eine Pause machen (κάνω διάλειμμα), Sport machen, Urlaub machen.",
        "Σε λογαριασμό το machen σημαίνει «κάνει (συνολικά)»: Das macht zehn Euro — σύνολο δέκα ευρώ."
