        "Πληθυντικός: die Männer (οι άντρες, με μεταφωνία). Γενική: des Mannes, δοτική πληθυντικού: den Männern. Σε σύνθετα: Ehemann, Geschäftsmann (πληθ. Geschäftsleute).",
        "Διαφορά από τη λέξη man: το man (κανείς, οι άνθρωποι γενικά) είναι αντωνυμία και γράφεται με μικρό και με ένα n. Τον άνθρωπο γενικά τον λέμε der Mensch."
