        "Τύποι: ich mag, du magst, er/sie/es mag, wir mögen, ihr mögt, sie mögen· mochte, hat gemocht. Είναι τροπικό ρήμα, αλλά συχνά στέκεται μόνο του με αιτιατική.",
        "Για ευγενική παράκληση χρησιμοποιείται το möchte: Ich möchte einen Kaffee — θα ήθελα έναν καφέ (από το mögen, αλλά ως ξεχωριστός τύπος)."
