        "Συχνοί συνδυασμοί: morgen früh (αύριο το πρωί), morgen Abend (αύριο το βράδυ), bis morgen (τα λέμε αύριο), übermorgen (μεθαύριο). Τα μέρη της ημέρας μετά το morgen γράφονται με κεφαλαίο: morgen Nachmittag.",
        "Διαφορά από το Morgen: der Morgen είναι ουσιαστικό «πρωί», ενώ morgen είναι επίρρημα «αύριο». Στην αρχή της πρότασης ξεχωρίζουν μόνο από τη σημασία."
