        "Μετά το nach ακολουθεί δοτική: nach dem Unterricht, nach der Arbeit. Για πόλεις και χώρες χωρίς άρθρο: nach Deutschland, nach Riga. Για χώρες με άρθρο χρησιμοποιείται in: in die Schweiz.",
