        "Τύποι: ich nehme, du nimmst, er nimmt· nahm, hat genommen. Προστακτική: Nimm! (με i, όχι «nehm»). Πάντα με αιτιατική.",
        "Χωριζόμενα παράγωγα: mitnehmen (παίρνω μαζί μου), wegnehmen (αφαιρώ, παίρνω από κάποιον), annehmen (δέχομαι), zunehmen (παίρνω βάρος)."
