        "Τύποι: probiert, probierte, hat probiert (χωρίς ge-, γιατί τελειώνει σε -ieren). Συνήθως με αιτιατική: etwas probieren. Χωριζόμενο παράγωγο: anprobieren (δοκιμάζω ρούχο).",
        "Ευγενικά μαζί με το mal: Probier mal! — Δοκίμασε!"
