        "Τύποι: schwimmt, schwamm, ist geschwommen (ισχυρό ρήμα). Με κατεύθυνση ο σύνθετος παρελθοντικός σχηματίζεται με ist: Sie ist über den See geschwommen· και για τη δραστηριότητα η πρότυπη γλώσσα χρησιμοποιεί συχνά ist (Ich bin gestern geschwommen), μερικές φορές hat.",
        "Για το «κάνω μπάνιο» στη θάλασσα ή στη λίμνη τα γερμανικά χρησιμοποιούν συνήθως το baden: Wir baden im Meer."
