        "Πτώσεις: αιτιατική Sie, δοτική Ihnen, κτητική αντωνυμία Ihr/Ihre (κι αυτή με κεφαλαίο): Ich danke Ihnen für Ihre Hilfe.",
        "Το Sie χρησιμοποιείται με αγνώστους, στη δουλειά, σε υπηρεσίες και σε καταστήματα. Σε φίλους, οικογένεια και παιδιά λέμε du (σε περισσότερους — ihr)."
