        "Μεταφορικά το unter μπορεί να σημαίνει ανάμεσα σε (unter Freunden — ανάμεσα σε φίλους), λιγότερο από (unter 18 Jahren — κάτω των 18 ετών) και υπό την επίδραση κάποιου ή υπό ορισμένες συνθήκες.",
