        "Το Zu εκφράζει επίσης σκοπό (zum Essen — για φαγητό), το «υπερβολικά» (zu heiß — υπερβολικά ζεστός) και λειτουργεί ως μόριο του απαρεμφάτου: Ich habe keine Lust, zu arbeiten.",
