        "Η λέξη Zug έχει και άλλες σημασίες: κίνηση (σε παιχνίδι), ρεύμα αέρα (der Zug), γνώρισμα χαρακτήρα (Charakterzug). Σε αυτή την κάρτα εξετάζεται το τρένο.",
