        "Βασική ιδέα: το der Appetit είναι ουσιαστικό αρσενικού γένους που σημαίνει «όρεξη» — την επιθυμία για φαγητό. Πληθυντικός πρακτικά δεν χρησιμοποιείται. Ο πιο συχνός συνδυασμός είναι Appetit haben (έχω όρεξη): Ich habe keinen Appetit.",
        "Το Guten Appetit! είναι ευχή πριν από το φαγητό, «καλή όρεξη». Όταν υπάρχει επιθυμία για συγκεκριμένο φαγητό, λέμε Appetit auf + αιτιατική: Appetit auf Eis.",
        "Το Der Appetit είναι κοντά στη λέξη der Hunger, αλλά η όρεξη είναι επιθυμία για φαγητό, ενώ η πείνα είναι σωματική ανάγκη."
